using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<TicketClassifierService> _logger;
    private string[]? _classLabels;

    public TicketClassifierService(IWebHostEnvironment env, ILogger<TicketClassifierService> logger)
    {
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
        _logger = logger;
    }

    public string ModelPath => _modelPath;
    public string[] ClassLabels => _classLabels ?? ["Billing", "General", "Technical"];

    public TrainingResponse TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        // Combine Subject + Description into a single text feature, then featurize with Priority
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model on {Path}", _dataPath);
        var model = pipeline.Fit(split.TrainSet);

        // Extract class labels from the trained model's label key mapping
        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
        model.LastTransformer.Transform(
            model.Transform(split.TrainSet)).Schema["PredictedLabel"]
            .GetKeyValues(ref labelBuffer);
        // If key-value extraction succeeds, use those labels; otherwise fall back to defaults
        if (labelBuffer.Length > 0)
        {
            _classLabels = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();
        }

        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

        _logger.LogInformation(
            "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        _mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        var perClass = new List<CategoryMetric>();
        for (var i = 0; i < metrics.PerClassLogLoss.Count; i++)
        {
            perClass.Add(new CategoryMetric
            {
                Category = ClassLabels.Length > i ? ClassLabels[i] : $"Class {i}",
                Precision = metrics.ConfusionMatrix.PerClassPrecision[i],
                Recall = metrics.ConfusionMatrix.PerClassRecall[i],
                F1Score = 2 * (metrics.ConfusionMatrix.PerClassPrecision[i] * metrics.ConfusionMatrix.PerClassRecall[i])
                    / (metrics.ConfusionMatrix.PerClassPrecision[i] + metrics.ConfusionMatrix.PerClassRecall[i]
                       + double.Epsilon),
            });
        }

        return new TrainingResponse
        {
            Status = "Model trained and saved successfully",
            Metrics = new EvaluationMetrics
            {
                MicroAccuracy = (float)metrics.MicroAccuracy,
                MacroAccuracy = (float)metrics.MacroAccuracy,
                LogLoss = (float)metrics.LogLoss,
                LogLossReduction = (float)metrics.LogLossReduction,
                PerClassMetrics = perClass,
            },
        };
    }
}

