using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly TicketClassifierService _classifierService;
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionPool;

    public TicketController(
        TicketClassifierService classifierService,
        PredictionEnginePool<TicketData, TicketPrediction> predictionPool)
    {
        _classifierService = classifierService;
        _predictionPool = predictionPool;
    }

    [HttpPost("train")]
    public ActionResult<TrainingResponse> Train()
    {
        var result = _classifierService.TrainAndEvaluate();
        return Ok(result);
    }

    [HttpPost("predict")]
    public ActionResult<PredictionResponse> Predict([FromBody] TicketRequest request)
    {
        if (!System.IO.File.Exists(_classifierService.ModelPath))
        {
            return BadRequest(new { error = "Model not trained yet. Call POST /api/ticket/train first." });
        }

        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority,
        };

        var prediction = _predictionPool.Predict(input);
        var labels = _classifierService.ClassLabels;
        var probabilities = new Dictionary<string, float>();
        for (var i = 0; i < prediction.Score.Length && i < labels.Length; i++)
        {
            probabilities[labels[i]] = prediction.Score[i];
        }

        return Ok(new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            Probabilities = probabilities,
        });
    }
}

