arguments.new_str:
var perClass = new List<CategoryMetric>();
for (var i = 0; i < metrics.PerClassLogLoss.Count; i++)
{
    var precision = Sanitize(metrics.ConfusionMatrix.PerClassPrecision[i]);
    var recall = Sanitize(metrics.ConfusionMatrix.PerClassRecall[i]);
    var f1 = (precision + recall) > 0
        ? 2 * precision * recall / (precision + recall)
        : 0;

    perClass.Add(new CategoryMetric
    {
        Category = ClassLabels.Length > i ? ClassLabels[i] : $"Class {i}",
        Precision = precision,
        Recall = recall,
        F1Score = f1,
    });
}

