3. using TicketClassifier.Models;
4. 
5. namespace TicketClassifier.Services;
6. 
7. public class TicketClassifierService
8. {
9.     private readonly MLContext _mlContext = new(seed: 42);
10.     private readonly string _dataPath;
11.     private readonly string _modelPath;
12.     private readonly ILogger<TicketClassifierService> _logger;
13.     private string[]? _classLabels;
14. 
15.     public TicketClassifierService(IWebHostEnvironment env, ILogger<TicketClassifierService> logger)
16.     {
17.         _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
18.         _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
19.         _logger = logger;
20.     }
21. 
22.     public string ModelPath => _modelPath;
23.     public string[] ClassLabels => _classLabels ?? ["Billing", "General", "Technical"];
24. 
25.     public TrainingResponse TrainAndEvaluate()
26.     {
27.         var data = _mlContext.Data.LoadFromTextFile<TicketData>(
28.             _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
29. 
30.         var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
31. 
32.         // Combine Subject + Description into a single text feature, then featurize with Priority
33.         var pipeline = _mlContext.Transforms.Conversion
34.                 .MapValueToKey("Label", nameof(TicketData.Category))
35.             .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
36.             .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
37.             .Append(_mlContext.Transforms.Concatenate("Features",
38.                 "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
39.             .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
40.                 labelColumnName: "Label", featureColumnName: "Features"))
41.             .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
42. 
43.         _logger.LogInformation("Training model on {Path}", _dataPath);
44.         var model = pipeline.Fit(split.TrainSet);
45. 
46.         // Extract class labels from the trained model's label key mapping
47.         var labelColumn = model.Transform(split.TrainSet).Schema["Label"];
48.         var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
49.         labelColumn.GetKeyValues(ref labelBuffer);
50.         if (labelBuffer.Length > 0)
51.         {
52.             _classLabels = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();
53.         }
54. 
55.         var predictions = model.Transform(split.TestSet);
56.         var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");
57. 
58.         _logger.LogInformation(
59.             "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
60.             metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);
61. 
62.         _mlContext.Model.Save(model, data.Schema, _modelPath);
63.         _logger.LogInformation("Model saved to {Path}", _modelPath);
64. 
65.         var perClass = new List<CategoryMetric>();
66.         for (var i = 0; i < metrics.PerClassLogLoss.Count; i++)
67.         {
68.             var precision = Sanitize(metrics.ConfusionMatrix.PerClassPrecision[i]);
